const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;padding:10px;overflow:hidden;color:var(--ink);background:transparent;font:13px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.card button{font:inherit;color:inherit;cursor:pointer}\n.main{display:grid;gap:6px;width:100%;height:100%;min-width:0;min-height:0;grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto auto auto minmax(0,1fr);grid-template-areas:\"hd\" \"cfg\" \"run\" \"tabs\" \"list\"}\n.hd{grid-area:hd;display:flex;align-items:center;gap:6px;min-width:0}\n.hd h1{margin:0;font-size:15px;font-weight:700;white-space:nowrap}\n.ro{font-size:10px;color:var(--muted);border:1px solid var(--line);border-radius:99px;padding:0 6px;white-space:nowrap}\n.gear{margin-left:auto;flex:none;border:1px solid var(--line);background:var(--button-paper,transparent);color:var(--ink);border-radius:8px;padding:2px 8px;font-size:11px}\n.chips{grid-area:cfg;display:flex;flex-wrap:wrap;gap:4px;min-width:0;padding:0;border:0;background:none;text-align:left}\n.chip{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;padding:2px 8px;border-radius:99px;background:var(--soft);color:var(--ink)}\n.run{grid-area:run;display:flex;align-items:center;gap:8px;min-width:0}\n.go{flex:none;min-height:34px;padding:0 18px;border:0;border-radius:10px;background:var(--accent);color:var(--on-accent);font-size:14px;font-weight:700;white-space:nowrap}\n.go:disabled{opacity:.6;cursor:default}\n.stat{min-width:0;font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.tabs{grid-area:tabs;display:flex;gap:4px;min-width:0;overflow-x:auto;scrollbar-width:none}\n.tabs.empty{display:none}\n.tab{flex:none;white-space:nowrap;border:1px solid var(--line);background:var(--button-paper,transparent);color:var(--ink);border-radius:99px;padding:2px 9px;font-size:11px}\n.tab[aria-pressed=\"true\"]{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.list{grid-area:list;display:flex;flex-direction:column;gap:6px;min-width:0;min-height:0;overflow-y:auto;overflow-x:hidden;padding-right:2px}\n.note,.hint,.warn{flex:none;font-size:11px;line-height:1.45;color:var(--muted);overflow-wrap:anywhere}\n.warn{color:var(--ink);padding:6px 8px;border:1px dashed var(--accent);border-radius:8px}\n.hint{padding:6px 0}\n.row{flex:none;display:flex;gap:7px;align-items:flex-start;min-width:0;padding:7px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.row.done{opacity:.6}\n.chk{flex:none;width:24px;height:24px;margin-top:1px;padding:0;border:1.5px solid var(--line);border-radius:50%;background:var(--button-paper,transparent);color:var(--on-accent);font-size:13px;line-height:1}\n.chk[aria-pressed=\"true\"]{background:var(--accent);border-color:var(--accent)}\n.open{flex:1;min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding:0;border:0;background:none;text-align:left}\n.tgs{display:flex;flex-wrap:wrap;gap:3px}\n.tg{font-size:10px;font-weight:700;line-height:16px;padding:0 6px;border-radius:6px;white-space:nowrap;background:var(--accent);color:var(--on-accent)}\n.tg.prepare{background:var(--accent-alt);color:var(--on-accent)}\n.tg.attend{background:transparent;color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}\n.subj{max-width:100%;font-weight:600;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}\n.meta{max-width:100%;font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.dt{display:flex;flex-direction:column;gap:8px;min-width:0;color:var(--ink)}\n.dt h3{margin:0 0 2px;font-size:11px;font-weight:600;color:var(--muted)}\n.dt p{margin:0;overflow-wrap:anywhere}\n.dt .box{display:flex;flex-direction:column;gap:6px;padding:8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.dt .foot{font-size:11px;color:var(--muted)}\n\n/* 3x3: \u7d27\u51d1\uff0c\u8bbe\u7f6e\u6536\u8fdb\u6309\u94ae\uff0c\u65e5\u5386\u8bf4\u660e\u7559\u5728\u5217\u8868\u9876\u90e8 */\n.card[data-size=\"3x3\"]{padding:8px}\n.card[data-size=\"3x3\"] .main{gap:4px}\n.card[data-size=\"3x3\"] .ro,\n.card[data-size=\"3x3\"] .chips{display:none}\n.card[data-size=\"3x3\"] .go{min-height:30px;padding:0 12px;font-size:13px}\n.card[data-size=\"3x3\"] .row{padding:5px 6px;gap:5px}\n.card[data-size=\"3x3\"] .subj{-webkit-line-clamp:1}\n.card[data-size=\"3x3\"] .chk{width:22px;height:22px}\n\n/* 6x3: \u5de6\u4fa7\u63a7\u5236\u3001\u53f3\u4fa7\u7b5b\u9009\u4e0e\u5217\u8868 */\n.card[data-size=\"6x3\"] .main{grid-template-columns:150px minmax(0,1fr);grid-template-rows:auto auto auto minmax(0,1fr);grid-template-areas:\"hd tabs\" \"cfg list\" \"run list\" \". list\"}\n.card[data-size=\"6x3\"] .tabs.empty{display:block}\n.card[data-size=\"6x3\"] .ro,\n.card[data-size=\"6x3\"] .chip.mb{display:none}\n.card[data-size=\"6x3\"] .run{flex-direction:column;align-items:stretch;gap:4px}\n.card[data-size=\"6x3\"] .stat{white-space:normal}\n.card[data-size=\"6x3\"] .subj{-webkit-line-clamp:1}\n\n/* 3x6: \u5355\u5217\uff0c\u9ad8\u5ea6\u5145\u8db3 */\n.card[data-size=\"3x6\"] .subj{-webkit-line-clamp:2}\n\n/* 6x6: \u5355\u5217\u5bbd\u677e */\n.card[data-size=\"6x6\"]{padding:14px}\n.card[data-size=\"6x6\"] .main{gap:8px}\n.card[data-size=\"6x6\"] .hd h1{font-size:17px}\n.card[data-size=\"6x6\"] .row{padding:9px 10px}\n.card[data-size=\"6x6\"] .subj{font-size:14px}\n.card[data-size=\"6x6\"] .meta{font-size:12px}\n.card[data-size=\"6x6\"] .note,\n.card[data-size=\"6x6\"] .hint,\n.card[data-size=\"6x6\"] .warn{font-size:12px}\n";
var MAIL_SOURCE='connected.mail.message-list';
var RANGES=[
  {value:'1',label:'今天'},{value:'3',label:'近 3 天'},{value:'7',label:'近 7 天'},
  {value:'14',label:'近 14 天'},{value:'30',label:'近 30 天'},{value:'custom',label:'自定义日期'}
];
var KINDS={reply:'要回复',prepare:'要准备',attend:'要参加'};
var RULES=[
  ['attend',/会议|邀请|参加|出席|面试|评审|研讨|沙龙|活动|发布会|meeting|invite|invitation|webinar|rsvp/i],
  ['prepare',/准备|材料|截止|到期|提交|汇报|报告|审阅|审核|待办|deadline|due\b|prepare|review|submit/i],
  ['reply',/回复|答复|回信|确认|请告知|请反馈|是否|尽快|麻烦|reply|respond|confirm|please|\?|？/i]
];

function pad(n){return n<10?'0'+n:''+n}
function fmtDay(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function fmtTime(d){return fmtDay(d)+' '+pad(d.getHours())+':'+pad(d.getMinutes())}
function shiftDay(s,n){
  var p=s.split('-');
  return fmtDay(new Date(Number(p[0]),Number(p[1])-1,Number(p[2])+n));
}
function parseDate(v){
  if(v==null||v==='')return null;
  var d=typeof v==='number'?new Date(v<1e12?v*1000:v):new Date(String(v));
  return isNaN(d.getTime())?null:d;
}
function txt(v){
  if(v==null)return '';
  if(Array.isArray(v))return v.map(txt).filter(Boolean).join('、');
  if(typeof v==='object')return txt(v.name||v.display_name||v.address||v.email||'');
  return String(v);
}
function firstArray(d,depth){
  if(Array.isArray(d))return d;
  if(!d||typeof d!=='object'||(depth||0)>3)return null;
  var ks=['messages','items','list','results','records','data'];
  for(var i=0;i<ks.length;i++){
    var r=firstArray(d[ks[i]],(depth||0)+1);
    if(r)return r;
  }
  return null;
}
function normMail(m){
  if(!m||typeof m!=='object')return null;
  var subj=txt(m.subject||m.title||m.name)||'（无主题）';
  var d=parseDate(m.date||m.received_at||m.receivedAt||m.received_time||m.internal_date||m.sent_at||m.time||m.timestamp);
  var id=txt(m.id||m.message_id||m.messageId||m.uid);
  var at=d?d.getTime():null;
  return {
    id:id,subject:subj,
    from:txt(m.from||m.sender||m.from_name||m.from_address),
    at:at,
    snippet:txt(m.snippet||m.preview||m.summary||m.abstract||m.body_preview),
    key:id||(subj+'|'+(at||''))
  };
}
function classify(mail){
  var text=mail.subject+' '+mail.snippet;
  var tags=[],why=[];
  RULES.forEach(function(r){
    var m=text.match(r[1]);
    if(m){tags.push(r[0]);why.push(KINDS[r[0]]+'：命中「'+m[0]+'」')}
  });
  return {tags:tags,why:why};
}
function calcRange(cfg,today){
  var p=cfg.preset||'7';
  if(p==='custom'&&cfg.from&&cfg.to&&cfg.from<=cfg.to)return {from:cfg.from,to:cfg.to};
  var n=Number(p)||7;
  return {from:shiftDay(today,-(n-1)),to:today};
}
function rangeLabel(cfg){
  var p=cfg.preset||'7';
  if(p==='custom')return (cfg.from&&cfg.to)?cfg.from+' ~ '+cfg.to:'自定义（未填日期）';
  for(var i=0;i<RANGES.length;i++)if(RANGES[i].value===p)return RANGES[i].label;
  return '近 7 天';
}
function buildSnap(data,range){
  var arr=firstArray(data,0)||[];
  var all=arr.map(normMail).filter(Boolean);
  var inR=all.filter(function(m){
    if(m.at==null)return true;
    var k=fmtDay(new Date(m.at));
    return k>=range.from&&k<=range.to;
  });
  inR.sort(function(a,b){return (b.at||0)-(a.at||0)});
  var items=[],rest=[];
  inR.forEach(function(m){
    var c=classify(m);
    var row={mail:m,tags:c.tags,why:c.why,key:m.key};
    if(c.tags.length)items.push(row);else rest.push(row);
  });
  return {at:Date.now(),range:range,total:all.length,inRange:inR.length,items:items,rest:rest};
}
function errText(e,hasSnap){
  var msg=String((e&&e.message)||e||'未知错误');
  if(/permission_denied|denied|not.?bound|unbound|未绑定/i.test(msg)){
    return '邮箱尚未连接：请先在平台为本卡片连接邮箱，再点「找出」。';
  }
  return '读取邮件失败（'+msg+'）。'+(hasSnap?'已保留上次结果。':'');
}

function mount(ctx){
  const {root,ui}=ctx;
  if(!ui.view)ui.view='main';
  if(!ui.tab)ui.tab='all';
  if(ui.view==='settings')root.append(viewSettings(ctx));
  else if(ui.view==='detail')root.append(viewDetail(ctx));
  else root.append(viewMain(ctx));
}

function runScan(ctx){
  const {ui,state,runAsync,fetchSource}=ctx;
  const range=calcRange(state.cfg||{},ctx.day());
  ui.scanN=(ui.scanN||0)+1;
  const key='scan'+ui.scanN;
  ui.job=key;
  runAsync(key,async function(){
    const data=await fetchSource(MAIL_SOURCE);
    const snap=buildSnap(data,range);
    ui.snap=snap;
    return {count:snap.items.length};
  });
}

function toggleChecked(ctx,key){
  return ctx.update(function(s){
    const c=Object.assign({},s.checked||{});
    if(c[key])delete c[key];else c[key]=true;
    return Object.assign({},s,{checked:c});
  }).catch(function(){});
}

function openSettings(ctx){
  const {ui,state}=ctx;
  const cfg=state.cfg||{};
  ui.draft={mailbox:cfg.mailbox||'',calendar:cfg.calendar||'',preset:cfg.preset||'7',from:cfg.from||'',to:cfg.to||''};
  ui.view='settings';
  ctx.redraw();
}

function viewMain(ctx){
  const {el,state,ui,redraw}=ctx;
  const cfg=state.cfg||{};
  const jobs=ui.jobs||{};
  const job=ui.job?jobs[ui.job]:null;
  const loading=!!(job&&job.status==='loading');
  const snap=ui.snap||null;
  const range=calcRange(cfg,ctx.day());

  const hd=el('div',{class:'hd'},
    el('h1',{},'查漏事项'),
    el('span',{class:'ro',title:'只读：不会回复、归档或修改邮件和日程'},'只读'),
    el('button',{type:'button',class:'gear','aria-label':'设置邮箱、日历和日期范围',onclick:function(){openSettings(ctx)}},'设置')
  );
  const chips=el('button',{type:'button',class:'chips','aria-label':'修改邮箱、日历和日期范围',onclick:function(){openSettings(ctx)}},
    el('span',{class:'chip mb'},'邮箱 '+(cfg.mailbox||'平台已绑定')),
    el('span',{class:'chip cal'},'日历 '+(cfg.calendar||'未选')+' · 未接入'),
    el('span',{class:'chip rg'},rangeLabel(cfg))
  );
  let statText='范围 '+range.from.slice(5)+' ~ '+range.to.slice(5);
  if(loading)statText='正在读取邮件…';
  else if(snap)statText='更新于 '+fmtTime(new Date(snap.at));
  const run=el('div',{class:'run'},
    el('button',{type:'button',class:'go',disabled:loading,onclick:function(){runScan(ctx)}},loading?'读取中…':(snap?'重新找出':'找出')),
    el('span',{class:'stat'},statText)
  );

  const cnt={all:0,reply:0,prepare:0,attend:0,rest:0};
  if(snap){
    cnt.all=snap.items.length;cnt.rest=snap.rest.length;
    snap.items.forEach(function(r){r.tags.forEach(function(t){cnt[t]++})});
  }
  const tabDefs=[['all','全部'],['reply','回复'],['prepare','准备'],['attend','参加'],['rest','其他']];
  const tabs=snap?el('div',{class:'tabs',role:'group','aria-label':'按类型筛选'},
    tabDefs.map(function(t){
      return el('button',{type:'button',class:'tab','aria-pressed':String(ui.tab===t[0]),onclick:function(){ui.tab=t[0];redraw()}},t[1]+' '+cnt[t[0]]);
    })
  ):el('div',{class:'tabs empty'});

  return el('div',{class:'main'},hd,chips,run,tabs,viewList(ctx,snap,job,loading,range));
}

function allRows(snap){return snap?snap.items.concat(snap.rest):[]}

function viewList(ctx,snap,job,loading,range){
  const {el,state,ui,redraw}=ctx;
  const cfg=state.cfg||{};
  const checked=state.checked||{};
  const kids=[];

  if(job&&job.status==='error'){
    kids.push(el('div',{class:'warn',role:'alert'},'⚠ '+errText(job.error,!!snap)));
  }
  if(snap){
    kids.push(el('div',{class:'note'},
      '邮件 '+snap.range.from+' ~ '+snap.range.to+'：共 '+snap.inRange+' 封，命中 '+snap.items.length+' 项。按主题/摘要关键词初筛，非 AI 判断，请对照原邮件核对。'));
  }
  kids.push(el('div',{class:'note cal-note'},
    '日历'+(cfg.calendar?'「'+cfg.calendar+'」':'')+'：平台暂无日历读取接口，本次未检查日程；已保存选择，接入后可用。'));

  if(!snap&&!loading&&!(job&&job.status==='error')){
    kids.push(el('div',{class:'hint'},
      '点「找出」读取已连接邮箱的邮件元数据，列出最近要回复、准备或参加的事项，每条附对应邮件。只读，不会改动邮件或日程。邮箱/日历名称仅作偏好保存，实际读取平台为本卡片绑定的邮箱。'));
  }
  if(loading&&!snap)kids.push(el('div',{class:'hint'},'正在读取邮件…'));

  if(snap){
    let rows=ui.tab==='rest'?snap.rest:snap.items.filter(function(r){return ui.tab==='all'||r.tags.indexOf(ui.tab)>=0});
    if(!rows.length){
      kids.push(el('div',{class:'hint'},ui.tab==='rest'?'没有其他邮件。':(snap.total===0?'邮箱源没有返回邮件。':'该范围内没有命中规则的邮件，可到「其他」查看未命中的邮件。')));
    }
    rows.forEach(function(r){kids.push(viewRow(ctx,r,!!checked[r.key]))});
  }
  return el('div',{class:'list'},kids);
}

function viewRow(ctx,r,done){
  const {el,ui,redraw}=ctx;
  const m=r.mail;
  const meta=(m.from||'发件人未提供')+' · '+(m.at?fmtTime(new Date(m.at)):'日期未提供');
  const tags=r.tags.map(function(t){return el('span',{class:'tg '+t},KINDS[t])});
  return el('div',{class:'row'+(done?' done':'')},
    el('button',{type:'button',class:'chk','aria-pressed':String(done),'aria-label':done?'取消已核对':'标记已核对',onclick:function(){toggleChecked(ctx,r.key)}},done?'✓':''),
    el('button',{type:'button',class:'open',onclick:function(){ui.sel=r.key;ui.view='detail';redraw()}},
      el('span',{class:'tgs'},tags),
      el('span',{class:'subj'},m.subject),
      el('span',{class:'meta'},meta)
    )
  );
}

function viewDetail(ctx){
  const {el,state,ui,redraw,panel}=ctx;
  const back=function(){ui.view='main';ui.sel=null;redraw()};
  const r=allRows(ui.snap).filter(function(x){return x.key===ui.sel})[0];
  if(!r)return panel({title:'核对',body:el('p',{},'找不到这条记录，请返回重新查找。'),onBack:back});
  const m=r.mail;
  const done=!!(state.checked||{})[r.key];
  const sec=function(label,val){return el('div',{class:'sec'},el('h3',{},label),el('p',{},val))};
  const body=el('div',{class:'dt'},
    sec('类型与依据',r.why.length?r.why.join('；'):'未命中任何关键词规则（仅在「其他」中列出）'),
    el('div',{class:'box'},
      el('h3',{},'对应邮件'),
      sec('主题',m.subject),
      sec('发件人',m.from||'未提供'),
      sec('收到时间',m.at?fmtTime(new Date(m.at)):'未提供'),
      sec('摘要',m.snippet||'未提供'),
      sec('邮件 ID',m.id||'未提供')
    ),
    el('div',{class:'box'},el('h3',{},'对应日程'),el('p',{},'日历读取尚未接入，无法关联日程；请到日历中自行核对。')),
    el('p',{class:'foot'},'本卡片只读：不会回复、归档或修改邮件和日程。「已核对」仅是卡片内的本地标记。')
  );
  return panel({
    title:r.tags.length?r.tags.map(function(t){return KINDS[t]}).join(' / '):'核对',
    body:body,
    actions:[{label:done?'取消已核对':'标记已核对',primary:true,onClick:function(){toggleChecked(ctx,r.key)}}],
    onBack:back
  });
}

function viewSettings(ctx){
  const {ui,editor}=ctx;
  const back=function(){ui.view='main';ui.draft=null;ctx.redraw()};
  return editor({
    title:'查漏设置',
    draft:ui.draft,
    submitLabel:'保存',
    onBack:back,
    fields:[
      {key:'mailbox',label:'邮箱（偏好，实际读取平台绑定邮箱）',type:'text',placeholder:'邮箱名称或地址'},
      {key:'calendar',label:'日历（偏好，读取暂未接入）',type:'text',placeholder:'日历名称'},
      {key:'preset',label:'日期范围',type:'select',options:RANGES},
      {key:'from',label:'开始日期（选自定义时）',type:'date'},
      {key:'to',label:'结束日期（选自定义时）',type:'date'}
    ],
    onSave:function(v){
      const p=v.preset||'7';
      if(p==='custom'&&(!v.from||!v.to||v.from>v.to))return '请填写有效的起止日期（开始不晚于结束）';
      const cfg={mailbox:(v.mailbox||'').trim(),calendar:(v.calendar||'').trim(),preset:p,from:v.from||'',to:v.to||''};
      return ctx.commit(function(s){return Object.assign({},s,{cfg:cfg})},Object.assign({},ui,{view:'main',draft:null}));
    }
  });
